export interface FareQuote {
  routeKey: string;
  baseFareCents: number;
  taxesCents: number;
  totalCents: number;
  currency: string;
  computedAt: number;
}

export interface FareSource {
  fetchBaseFare(origin: string, destination: string, date: string): Promise<{ cents: number; currency: string }>;
}

const QUOTE_TTL_MS = 60_000;
const TAX_RATE = 0.12;

export class PricingEngine {
  private readonly quotes = new Map<string, FareQuote>();

  constructor(private readonly source: FareSource, private readonly now: () => number = Date.now) {}

  async quote(origin: string, destination: string, date: string): Promise<FareQuote> {
    const routeKey = `${origin}:${destination}:${date}`;
    const cached = this.quotes.get(routeKey);
    if (cached && this.now() - cached.computedAt < QUOTE_TTL_MS) {
      return cached;
    }

    const base = await this.source.fetchBaseFare(origin, destination, date);
    const taxesCents = Math.round(base.cents * TAX_RATE);
    const fresh: FareQuote = {
      routeKey,
      baseFareCents: base.cents,
      taxesCents,
      totalCents: base.cents + taxesCents,
      currency: base.currency,
      computedAt: this.now(),
    };
    this.quotes.set(routeKey, fresh);
    return fresh;
  }

  invalidate(routeKey: string): void {
    this.quotes.delete(routeKey);
  }
}

export type LoyaltyTier = "none" | "silver" | "gold" | "platinum";

const DISCOUNTS: Record<LoyaltyTier, number> = {
  none: 0,
  silver: 0.03,
  gold: 0.07,
  platinum: 0.1,
};

export interface TravelerProfile {
  travelerId: string;
  tier: LoyaltyTier;
}

export function discountRate(profile: TravelerProfile): number {
  return DISCOUNTS[profile.tier] ?? 0;
}

import { FareQuote, PricingEngine } from "./pricingEngine";
import { TravelerProfile, discountRate } from "./loyalty";

export interface BookingRepository {
  insert(record: BookingRecord): Promise<void>;
}

export interface PaymentGateway {
  charge(travelerId: string, amountCents: number, currency: string, reference: string): Promise<{ chargeId: string }>;
}

export interface BookingRequest {
  bookingId: string;
  origin: string;
  destination: string;
  date: string;
  traveler: TravelerProfile;
}

export interface BookingRecord {
  bookingId: string;
  travelerId: string;
  routeKey: string;
  chargedCents: number;
  currency: string;
  chargeId: string;
}

export class BookingService {
  constructor(
    private readonly pricing: PricingEngine,
    private readonly payments: PaymentGateway,
    private readonly bookings: BookingRepository,
  ) {}

  async book(req: BookingRequest): Promise<BookingRecord> {
    const quote = await this.pricing.quote(req.origin, req.destination, req.date);
    const priced = this.applyLoyalty(quote, req.traveler);

    if (priced.totalCents <= 0) {
      throw new Error(`invalid fare for ${priced.routeKey}: ${priced.totalCents}`);
    }

    const { chargeId } = await this.payments.charge(
      req.traveler.travelerId,
      priced.totalCents,
      priced.currency,
      req.bookingId,
    );

    const record: BookingRecord = {
      bookingId: req.bookingId,
      travelerId: req.traveler.travelerId,
      routeKey: priced.routeKey,
      chargedCents: priced.totalCents,
      currency: priced.currency,
      chargeId,
    };
    await this.bookings.insert(record);
    return record;
  }

  private applyLoyalty(quote: FareQuote, traveler: TravelerProfile): FareQuote {
    const rate = discountRate(traveler);
    if (rate === 0) {
      return quote;
    }
    const discount = Math.round(quote.baseFareCents * rate);
    quote.baseFareCents -= discount;
    quote.totalCents = quote.baseFareCents + quote.taxesCents;
    return quote;
  }
}
